(()=>{const essay=window.ESSAY_MEMORY_LESSONS["opinion:33"];if(!essay)throw Error('Missing exact source for opinion:33');essay.learningSentences=[{"paragraph":0,"index":0,"role":"Background（背景）","english":"Crime is a serious social problem, and many people believe that offenders should simply be sent to prison.","chinese":"犯罪是一個嚴重的社會問題，而許多人認為罪犯應該直接被送入監獄。","words":[["Crime",0,0.22],["is",0.22,0.66],["a",0.66,0.76],["serious",0.76,1.14],["social",1.14,1.5],["problem",1.5,2.08],["and",2.58,2.66],["many",2.66,2.82],["people",2.82,3.22],["believe",3.22,3.64],["that",3.64,3.86],["offenders",3.86,4.12],["should",4.12,4.66],["simply",4.66,4.96],["be",4.96,5.18],["sent",5.18,5.42],["to",5.42,5.58],["prison",5.58,5.78]],"start":0,"end":6.493,"sourceIndices":[0]},{"paragraph":0,"index":1,"role":"Transition（轉折）","english":"While imprisonment may appear to be the most direct response to criminal behaviour, I firmly believe that it is not the best general solution.","chinese":"雖然監禁看起來可能是對犯罪行為最直接的回應，我堅定地認為，這並不是一般情況下最好的解決方法。","words":[["While",6.573,6.713],["imprisonment",6.713,7.053],["may",7.053,7.653],["appear",7.653,7.893],["to",7.893,8.113],["be",8.113,8.213],["the",8.213,8.353],["most",8.353,8.533],["direct",8.533,8.933],["response",8.933,9.473],["to",9.473,9.813],["criminal",9.813,10.073],["behaviour",10.073,10.553],["I",11.413,11.473],["firmly",11.473,11.753],["believe",11.753,12.293],["that",12.293,12.573],["it",12.573,12.673],["is",12.673,12.873],["not",12.873,13.073],["the",13.073,13.253],["best",13.253,13.433],["general",13.433,13.873],["solution",13.873,14.573]],"start":6.413,"end":15.22,"sourceIndices":[1,2]},{"paragraph":0,"index":2,"role":"Thesis Statement（中心論點）","english":"In most cases, rehabilitation and carefully supervised community-based punishments are more effective because they address the causes of crime rather than merely hiding criminals from society.","chinese":"在大多數情況下，改造和受到仔細監管的社區式懲罰更加有效，因為它們處理的是犯罪的根源，而不是僅僅把罪犯從社會中隱藏起來。","words":[["In",15.3,15.4],["most",15.4,15.54],["cases",15.54,15.94],["rehabilitation",16.5,16.98],["and",16.98,17.76],["carefully",17.76,18.16],["supervised",18.16,18.84],["community-based",18.84,19.96],["punishments",19.96,20.34],["are",20.34,21.26],["more",21.26,21.42],["effective",21.42,21.84],["because",21.84,22.8],["they",22.8,23.02],["address",23.02,23.28],["the",23.28,23.6],["causes",23.6,23.92],["of",23.92,24.2],["crime",24.2,24.54],["rather",24.54,25.32],["than",25.32,25.64],["merely",25.64,25.84],["hiding",25.84,26.28],["criminals",26.28,26.64],["from",26.64,27.18],["society",27.18,27.5]],"start":15.14,"end":28.591,"sourceIndices":[3]},{"paragraph":1,"index":0,"role":"Topic Sentence（主題句）","english":"Supporters of prison often argue that it protects the public and sends a clear warning to potential offenders.","chinese":"支持監禁的人經常認為，監獄能保護公眾，並向潛在犯罪者發出清晰警告。","words":[["Supporters",28.671,28.951],["of",28.951,29.331],["prison",29.331,29.551],["often",29.551,30.051],["argue",30.051,30.611],["that",30.611,30.891],["it",30.891,30.991],["protects",30.991,31.251],["the",31.251,31.551],["public",31.551,31.811],["and",31.811,32.431],["sends",32.431,32.631],["a",32.631,32.791],["clear",32.791,33.031],["warning",33.031,33.431],["to",33.431,33.651],["potential",33.651,33.851],["offenders",33.851,34.391]],"start":28.511,"end":35.249,"sourceIndices":[4]},{"paragraph":1,"index":1,"role":"Supporting Detail 1（支持細節一）","english":"This view is understandable because dangerous criminals can cause real harm if they remain free.","chinese":"這種看法是可以理解的，因為危險的罪犯如果仍然自由，確實可能造成真正的傷害。","words":[["This",35.329,35.509],["view",35.509,35.749],["is",35.749,35.989],["understandable",35.989,36.489],["because",36.489,37.469],["dangerous",37.469,37.889],["criminals",37.889,38.489],["can",38.489,39.129],["cause",39.129,39.409],["real",39.409,39.709],["harm",39.709,40.149],["if",40.149,40.469],["they",40.469,40.649],["remain",40.649,40.889],["free",40.889,41.269]],"start":35.169000000000004,"end":41.885000000000005,"sourceIndices":[5]},{"paragraph":1,"index":2,"role":"Logic Chain（邏輯鏈）","english":"However, prison often treats the symptom rather than the disease.","chinese":"然而，監獄往往處理的是症狀，而不是疾病本身。","words":[["However",41.965,42.245],["prison",42.565,42.865],["often",42.865,43.185],["treats",43.185,43.525],["the",43.525,43.785],["symptom",43.785,44.105],["rather",44.105,44.705],["than",44.705,45.025],["the",45.025,45.065],["disease",45.065,45.325]],"start":41.80500000000001,"end":46.175000000000004,"sourceIndices":[6]},{"paragraph":1,"index":3,"role":"Supporting Detail 2（支持細節二）","english":"Many offenders commit crimes because of addiction, poor education, unemployment, or unstable family backgrounds.","chinese":"許多犯罪者犯罪，是因為成癮、教育不足、失業，或不穩定的家庭背景。","words":[["Many",46.255,46.495],["offenders",46.495,46.715],["commit",46.715,47.355],["crimes",47.355,47.715],["because",47.715,48.495],["of",48.495,48.635],["addiction",48.635,48.935],["poor",49.495,49.655],["education",49.655,50.295],["unemployment",50.755,51.015],["or",51.675,51.855],["unstable",51.855,52.275],["family",52.275,52.895],["backgrounds",52.895,53.315]],"start":46.095000000000006,"end":54.156,"sourceIndices":[7]},{"paragraph":1,"index":4,"role":"Logic Chain（邏輯鏈）","english":"If these problems are ignored, prison can become a revolving door: criminals enter, serve their sentence, and return to society with the same weaknesses, or sometimes even worse ones.","chinese":"如果這些問題被忽視，監獄就可能變成一扇旋轉門：罪犯進去、服刑，然後帶著同樣的弱點，甚至有時帶著更嚴重的問題回到社會。","words":[["If",54.236,54.376],["these",54.376,54.516],["problems",54.516,54.876],["are",54.876,55.216],["ignored",55.216,55.516],["prison",56.196,56.316],["can",56.316,56.556],["become",56.556,56.716],["a",56.716,57.036],["revolving",57.036,57.296],["door",57.296,57.836],["criminals",58.556,58.956],["enter",58.956,59.316],["serve",59.716,59.956],["their",59.956,60.236],["sentence",60.236,60.616],["and",61.136,61.236],["return",61.236,61.496],["to",61.496,61.776],["society",61.776,62.096],["with",62.096,62.616],["the",62.616,62.736],["same",62.736,62.996],["weaknesses",62.996,63.316],["or",64.036,64.236],["sometimes",64.236,64.716],["even",64.716,65.196],["worse",65.196,65.436],["ones",65.436,65.756]],"start":54.076,"end":66.382,"sourceIndices":[8]},{"paragraph":1,"index":5,"role":"Example（例子）","english":"For example, a young person who commits a minor theft may leave prison with fewer job prospects and stronger links to hardened criminals.","chinese":"例如，一個犯下輕微盜竊的年輕人，出獄後可能會有更少的就業機會，並與慣犯建立更深的聯繫。","words":[["For",66.462,66.582],["example",66.582,66.842],["a",67.362,67.522],["young",67.522,67.702],["person",67.702,68.082],["who",68.082,68.402],["commits",68.402,68.722],["a",68.722,68.902],["minor",68.902,69.082],["theft",69.082,69.522],["may",69.522,70.142],["leave",70.142,70.382],["prison",70.382,70.662],["with",70.662,71.042],["fewer",71.042,71.262],["job",71.262,71.602],["prospects",71.602,72.042],["and",72.502,72.822],["stronger",72.822,73.142],["links",73.142,73.522],["to",73.522,73.782],["hardened",73.782,74.022],["criminals",74.022,74.482]],"start":66.302,"end":75.259,"sourceIndices":[9]},{"paragraph":1,"index":6,"role":"Conclusion（段落總結）","english":"In this sense, prison can punish crime without actually reducing it.","chinese":"從這個意義上說，監獄可以懲罰犯罪，卻未必真正減少犯罪。","words":[["In",75.339,75.439],["this",75.439,75.559],["sense",75.559,75.859],["prison",76.199,76.459],["can",76.459,76.739],["punish",76.739,77.039],["crime",77.039,77.439],["without",77.439,77.839],["actually",77.839,78.419],["reducing",78.419,78.819],["it",78.819,79.119]],"start":75.179,"end":79.925,"sourceIndices":[10]},{"paragraph":2,"index":0,"role":"Topic Sentence（主題句）","english":"A better approach is to combine punishment with rehabilitation.","chinese":"更好的方法是把懲罰與改造結合起來。","words":[["A",80.005,80.085],["better",80.085,80.265],["approach",80.265,80.825],["is",80.825,81.165],["to",81.165,81.325],["combine",81.325,81.545],["punishment",81.545,82.085],["with",82.085,82.745],["rehabilitation",82.745,83.185]],"start":79.845,"end":84.279,"sourceIndices":[11]},{"paragraph":2,"index":1,"role":"Supporting Detail 1（支持細節一）","english":"Offenders should still face consequences, but those consequences should help them rebuild their lives and repay society.","chinese":"犯罪者仍然應該承擔後果，但這些後果應該幫助他們重建生活，並回饋社會。","words":[["Offenders",84.359,84.739],["should",84.739,85.079],["still",85.079,85.359],["face",85.359,85.619],["consequences",85.619,86.019],["but",87.059,87.159],["those",87.159,87.359],["consequences",87.359,87.819],["should",87.819,88.399],["help",88.399,88.599],["them",88.599,88.879],["rebuild",88.879,89.119],["their",89.119,89.519],["lives",89.519,89.919],["and",89.919,90.459],["repay",90.459,90.659],["society",90.659,91.139]],"start":84.199,"end":91.94,"sourceIndices":[12]},{"paragraph":2,"index":2,"role":"Supporting Detail 2（支持細節二）","english":"Drug treatment, psychological counselling, vocational training, community service, and victim compensation can all make punishment more constructive.","chinese":"戒毒治療、心理輔導、職業培訓、社區服務，以及對受害者的賠償，都可以讓懲罰變得更具建設性。","words":[["Drug",92.02,92.2],["treatment",92.2,92.58],["psychological",93.02,93.42],["counselling",93.42,94.18],["vocational",94.78,94.96],["training",94.96,95.74],["community",96.22,96.52],["service",96.52,97.08],["and",97.46,97.48],["victim",97.48,97.7],["compensation",97.7,98.44],["can",98.75,99.16],["all",99.16,99.38],["make",99.38,99.62],["punishment",99.62,99.96],["more",99.96,100.52],["constructive",100.52,100.98]],"start":91.86,"end":101.798,"sourceIndices":[13]},{"paragraph":2,"index":3,"role":"Example（例子）","english":"For instance, someone who has committed a non-violent offence could be required to work in the community while attending training courses and meeting strict supervision conditions.","chinese":"例如，一個犯下非暴力罪行的人，可以被要求在社區工作，同時參加培訓課程，並遵守嚴格的監管條件。","words":[["For",101.878,101.998],["instance",101.998,102.218],["someone",102.818,103.218],["who",103.218,103.418],["has",103.418,103.558],["committed",103.558,103.918],["a",103.918,104.178],["non-violent",104.178,104.818],["offence",104.818,105.338],["could",105.338,105.978],["be",105.978,106.078],["required",106.078,106.438],["to",106.438,106.738],["work",106.738,106.938],["in",106.938,107.098],["the",107.098,107.178],["community",107.178,107.578],["while",107.578,108.178],["attending",108.178,108.458],["training",108.458,108.878],["courses",108.878,109.358],["and",109.358,109.998],["meeting",109.998,110.218],["strict",110.218,110.678],["supervision",110.678,111.018],["conditions",111.018,111.718]],"start":101.718,"end":112.637,"sourceIndices":[14]},{"paragraph":2,"index":4,"role":"Logic Chain（邏輯鏈）","english":"This approach does not excuse the crime; rather, it turns punishment into a ladder instead of a cage.","chinese":"這種方法並不是在為犯罪開脫；相反，它把懲罰變成一把梯子，而不是一個牢籠。","words":[["This",112.717,112.837],["approach",112.837,113.217],["does",113.217,113.497],["not",113.497,113.697],["excuse",113.697,114.057],["the",114.057,114.337],["crime",114.337,114.477],["rather",115.517,115.527],["it",115.897,116.057],["turns",116.057,116.357],["punishment",116.357,116.677],["into",116.677,117.197],["a",117.197,117.317],["ladder",117.317,117.557],["instead",117.557,118.017],["of",118.017,118.237],["a",118.237,118.297],["cage",118.297,118.537]],"start":112.557,"end":119.274,"sourceIndices":[15]},{"paragraph":2,"index":5,"role":"Effect（影響）","english":"It gives offenders a realistic path back into society, which ultimately makes communities safer.","chinese":"它給犯罪者一條實際可行的回歸社會之路，而這最終會令社區更加安全。","words":[["It",119.354,119.434],["gives",119.434,119.574],["offenders",119.574,119.854],["a",119.854,120.434],["realistic",120.434,120.714],["path",120.714,121.294],["back",121.294,121.654],["into",121.654,121.874],["society",121.874,122.294],["which",122.974,123.074],["ultimately",123.074,123.474],["makes",123.474,123.954],["communities",123.954,124.174],["safer",124.174,124.834]],"start":119.194,"end":125.839,"sourceIndices":[16]},{"paragraph":3,"index":0,"role":"Reiterating Stance（重申立場）","english":"In conclusion, prison may look like a strong solution, but it is often a blunt instrument.","chinese":"總結來說，監獄可能看起來是一種有力的解決方法，但它往往是一種粗糙不精準的工具。","words":[["In",125.919,126.019],["conclusion",126.019,126.419],["prison",126.999,127.279],["may",127.279,127.579],["look",127.579,127.799],["like",127.799,127.999],["a",127.999,128.099],["strong",128.099,128.339],["solution",128.339,128.819],["but",129.519,129.599],["it",129.599,129.699],["is",129.699,129.819],["often",129.819,130.159],["a",130.159,130.319],["blunt",130.319,130.479],["instrument",130.479,130.999]],"start":125.759,"end":131.72899999999998,"sourceIndices":[17]},{"paragraph":3,"index":1,"role":"Reiterating Arguments（重申論點）","english":"I believe that rehabilitation and structured alternatives are better ways to deal with most criminals because they reduce reoffending, repair damage, and help society break the cycle of crime.","chinese":"我認為，改造和有結構的替代方案是處理大多數罪犯更好的方法，因為它們能減少再犯、修補傷害，並幫助社會打破犯罪循環。","words":[["I",131.809,131.929],["believe",131.929,132.229],["that",132.229,132.509],["rehabilitation",132.509,132.909],["and",132.909,133.709],["structured",133.709,134.009],["alternatives",134.009,134.789],["are",134.789,135.489],["better",135.489,135.709],["ways",135.709,136.049],["to",136.049,136.289],["deal",136.289,136.489],["with",136.489,136.709],["most",136.709,136.889],["criminals",136.889,137.269],["because",137.929,138.229],["they",138.229,138.529],["reduce",138.529,138.769],["reoffending",138.769,139.609],["repair",140.069,140.229],["damage",140.229,140.789],["and",141.229,141.269],["help",141.269,141.449],["society",141.449,141.929],["break",141.929,142.669],["the",142.669,142.889],["cycle",142.889,143.129],["of",143.129,143.409],["crime",143.409,143.629]],"start":131.649,"end":144.029,"sourceIndices":[18]}];essay.meta={"topic":"監禁、犯罪成因與有結構的改造方案","summary":"作者認為監獄並非處理大多數罪犯的一般最佳方法，同時承認危險罪犯自由可能傷人。若成癮、教育、失業等成因未解，監禁或令問題循環；懲罰結合治療、職訓、社區工作、賠償及嚴格監管，較可能協助重建並減少再犯。"};essay.support={"sentences":[{"simple":"Crime is a serious problem in society, and many people think offenders should just go to prison.","synonyms":[{"original":"serious social problem","simple":"serious problem in society","meaning":"嚴重社會問題"},{"original":"many people believe","simple":"many people think","meaning":"許多人認為"},{"original":"offenders","simple":"offenders","meaning":"罪犯"},{"original":"simply be sent to prison","simple":"just go to prison","meaning":"直接入獄"}],"chunks":["Crime is a serious social problem,","and many people believe that offenders should simply be sent to prison."],"simpleChunks":["Crime is a serious problem in society,","and many people think offenders should just go to prison."]},{"simple":"Although prison may seem the simplest answer to crime, I strongly believe it is not the best answer in general.","synonyms":[{"original":"While imprisonment may appear","simple":"Although prison may seem","meaning":"雖然監禁看似"},{"original":"most direct response","simple":"simplest answer","meaning":"最直接回應"},{"original":"firmly believe","simple":"strongly believe","meaning":"堅定認為"},{"original":"not the best general solution","simple":"not the best answer in general","meaning":"非一般最佳解方"}],"chunks":["While imprisonment may appear to be the most direct response to criminal behaviour,","I firmly believe that it is not the best general solution."],"simpleChunks":["Although prison may seem the simplest answer to crime,","I strongly believe it is not the best answer in general."]},{"simple":"In most situations, helping offenders change and using well-watched punishments in the community work better, because they deal with why crimes happen instead of just keeping offenders out of sight.","synonyms":[{"original":"In most cases","simple":"In most situations","meaning":"在大多數情況"},{"original":"rehabilitation","simple":"helping offenders change","meaning":"改造"},{"original":"carefully supervised community-based punishments","simple":"well-watched punishments in the community","meaning":"受嚴密監管的社區刑罰"},{"original":"address the causes of crime","simple":"deal with why crimes happen","meaning":"處理犯罪成因"},{"original":"merely hiding criminals","simple":"just keeping offenders out of sight","meaning":"僅把罪犯藏起"}],"chunks":["In most cases, rehabilitation and carefully supervised community-based punishments are more effective","because they address the causes of crime","rather than merely hiding criminals from society."],"simpleChunks":["In most situations, helping offenders change and using well-watched punishments in the community work better,","because they deal with why crimes happen","instead of just keeping offenders out of sight."]},{"simple":"People who support prison often say it keeps the public safe and gives a clear warning to people who might break the law.","synonyms":[{"original":"Supporters of prison","simple":"People who support prison","meaning":"支持監禁者"},{"original":"protects the public","simple":"keeps the public safe","meaning":"保護公眾"},{"original":"potential offenders","simple":"people who might break the law","meaning":"潛在違法者"},{"original":"sends a clear warning","simple":"gives a clear warning","meaning":"清楚警告"}],"chunks":["Supporters of prison often argue that it protects the public","and sends a clear warning to potential offenders."],"simpleChunks":["People who support prison often say it keeps the public safe","and gives a clear warning to people who might break the law."]},{"simple":"This idea makes sense because dangerous offenders could really hurt people if they were free.","synonyms":[{"original":"This view is understandable","simple":"This idea makes sense","meaning":"這看法可理解"},{"original":"dangerous criminals","simple":"dangerous offenders","meaning":"危險罪犯"},{"original":"cause real harm","simple":"really hurt people","meaning":"造成真正傷害"},{"original":"remain free","simple":"were free","meaning":"保持自由"}],"chunks":["This view is understandable","because dangerous criminals can cause real harm if they remain free."],"simpleChunks":["This idea makes sense","because dangerous offenders could really hurt people if they were free."]},{"simple":"But prison often deals with the visible problem instead of what causes it.","synonyms":[{"original":"However","simple":"But","meaning":"然而"},{"original":"treats the symptom","simple":"deals with the visible problem","meaning":"處理症狀"},{"original":"rather than the disease","simple":"instead of what causes it","meaning":"而非根本病因"}],"chunks":["However, prison often treats the symptom","rather than the disease."],"simpleChunks":["But prison often deals with the visible problem","instead of what causes it."]},{"simple":"Many offenders break the law because of problems with drugs or alcohol, too little education, no job or an unstable family life.","synonyms":[{"original":"commit crimes","simple":"break the law","meaning":"犯罪"},{"original":"addiction","simple":"problems with drugs or alcohol","meaning":"成癮"},{"original":"poor education","simple":"too little education","meaning":"教育不足"},{"original":"unemployment","simple":"no job","meaning":"失業"},{"original":"unstable family backgrounds","simple":"unstable family life","meaning":"家庭不穩定"}],"chunks":["Many offenders commit crimes because of addiction, poor education,","unemployment, or unstable family backgrounds."],"simpleChunks":["Many offenders break the law because of problems with drugs or alcohol, too little education,","no job or an unstable family life."]},{"simple":"If we ignore these problems, prison can become a cycle: offenders go in, finish their time and return to society with the same problems or sometimes worse ones.","synonyms":[{"original":"If these problems are ignored","simple":"If we ignore these problems","meaning":"若忽略這些問題"},{"original":"revolving door","simple":"cycle","meaning":"旋轉門／循環"},{"original":"serve their sentence","simple":"finish their time","meaning":"服刑"},{"original":"same weaknesses","simple":"same problems","meaning":"同樣弱點"},{"original":"worse ones","simple":"worse ones","meaning":"更壞問題"}],"chunks":["If these problems are ignored, prison can become a revolving door:","criminals enter, serve their sentence, and return to society with the same weaknesses,","or sometimes even worse ones."],"simpleChunks":["If we ignore these problems, prison can become a cycle:","offenders go in, finish their time and return to society with the same problems","or sometimes worse ones."]},{"simple":"For example, a young person who steals something small may come out of prison with fewer chances of getting a job and closer ties to people who commit serious crimes.","synonyms":[{"original":"minor theft","simple":"steals something small","meaning":"輕微盜竊"},{"original":"leave prison","simple":"come out of prison","meaning":"出獄"},{"original":"fewer job prospects","simple":"fewer chances of getting a job","meaning":"較少工作機會"},{"original":"stronger links to hardened criminals","simple":"closer ties to people who commit serious crimes","meaning":"更接近慣犯"}],"chunks":["For example, a young person who commits a minor theft","may leave prison with fewer job prospects and stronger links to hardened criminals."],"simpleChunks":["For example, a young person who steals something small","may come out of prison with fewer chances of getting a job and closer ties to people who commit serious crimes."]},{"simple":"In this way, prison can punish an offence without really making future crime less common.","synonyms":[{"original":"In this sense","simple":"In this way","meaning":"從這角度"},{"original":"punish crime","simple":"punish an offence","meaning":"懲罰罪行"},{"original":"without actually reducing it","simple":"without really making future crime less common","meaning":"卻未必減少犯罪"}],"chunks":["In this sense, prison can punish crime","without actually reducing it."],"simpleChunks":["In this way, prison can punish an offence","without really making future crime less common."]},{"simple":"A better plan is to punish offenders while also helping them change.","synonyms":[{"original":"better approach","simple":"better plan","meaning":"更好方法"},{"original":"combine punishment with rehabilitation","simple":"punish offenders while also helping them change","meaning":"結合懲罰與改造"}],"chunks":["A better approach is to combine punishment","with rehabilitation."],"simpleChunks":["A better plan is to punish offenders","while also helping them change."]},{"simple":"Offenders should still face a penalty, but it should help them put their lives back together and give something back to society.","synonyms":[{"original":"face consequences","simple":"face a penalty","meaning":"承擔後果"},{"original":"rebuild their lives","simple":"put their lives back together","meaning":"重建生活"},{"original":"repay society","simple":"give something back to society","meaning":"回饋社會"}],"chunks":["Offenders should still face consequences,","but those consequences should help them rebuild their lives and repay society."],"simpleChunks":["Offenders should still face a penalty,","but it should help them put their lives back together and give something back to society."]},{"simple":"Help with drug problems, talking therapy, job training, community work and payments to victims can all make punishment do more good.","synonyms":[{"original":"Drug treatment","simple":"Help with drug problems","meaning":"戒毒治療"},{"original":"psychological counselling","simple":"talking therapy","meaning":"心理輔導"},{"original":"vocational training","simple":"job training","meaning":"職業培訓"},{"original":"community service","simple":"community work","meaning":"社區服務"},{"original":"victim compensation","simple":"payments to victims","meaning":"受害者賠償"},{"original":"more constructive","simple":"do more good","meaning":"更具建設性"}],"chunks":["Drug treatment, psychological counselling, vocational training, community service,","and victim compensation can all make punishment more constructive."],"simpleChunks":["Help with drug problems, talking therapy, job training, community work","and payments to victims can all make punishment do more good."]},{"simple":"For example, a person who did a crime without violence could have to work in the community, take training classes and follow strict rules set by people watching them.","synonyms":[{"original":"non-violent offence","simple":"crime without violence","meaning":"非暴力罪行"},{"original":"required to work in the community","simple":"have to work in the community","meaning":"須在社區工作"},{"original":"attending training courses","simple":"take training classes","meaning":"參加培訓"},{"original":"strict supervision conditions","simple":"strict rules set by people watching them","meaning":"嚴格監管條件"}],"chunks":["For instance, someone who has committed a non-violent offence","could be required to work in the community","while attending training courses and meeting strict supervision conditions."],"simpleChunks":["For example, a person who did a crime without violence","could have to work in the community, take training classes","and follow strict rules set by people watching them."]},{"simple":"This plan does not say the crime was acceptable; instead, it makes punishment a way to move forward rather than just a locked room.","synonyms":[{"original":"does not excuse the crime","simple":"does not say the crime was acceptable","meaning":"並非為罪行開脫"},{"original":"rather","simple":"instead","meaning":"相反"},{"original":"turns punishment into a ladder","simple":"makes punishment a way to move forward","meaning":"把懲罰化為梯子"},{"original":"instead of a cage","simple":"rather than just a locked room","meaning":"而非牢籠"}],"chunks":["This approach does not excuse the crime;","rather, it turns punishment into a ladder instead of a cage."],"simpleChunks":["This plan does not say the crime was acceptable;","instead, it makes punishment a way to move forward rather than just a locked room."]},{"simple":"It gives offenders a practical way to return to society, which can make communities safer in the end.","synonyms":[{"original":"realistic path back into society","simple":"practical way to return to society","meaning":"實際回歸之路"},{"original":"ultimately","simple":"in the end","meaning":"最終"},{"original":"communities safer","simple":"communities safer","meaning":"社區更安全"}],"chunks":["It gives offenders a realistic path back into society,","which ultimately makes communities safer."],"simpleChunks":["It gives offenders a practical way to return to society,","which can make communities safer in the end."]},{"simple":"In short, prison may seem like a strong answer, but it is often too rough a tool.","synonyms":[{"original":"In conclusion","simple":"In short","meaning":"總結"},{"original":"strong solution","simple":"strong answer","meaning":"有力解方"},{"original":"blunt instrument","simple":"too rough a tool","meaning":"粗糙工具"}],"chunks":["In conclusion, prison may look like a strong solution,","but it is often a blunt instrument."],"simpleChunks":["In short, prison may seem like a strong answer,","but it is often too rough a tool."]},{"simple":"I think helping offenders change and using carefully planned other punishments work better for most offenders because they can reduce repeated crime, fix harm and help society stop the cycle of crime.","synonyms":[{"original":"rehabilitation","simple":"helping offenders change","meaning":"改造"},{"original":"structured alternatives","simple":"carefully planned other punishments","meaning":"有結構替代刑罰"},{"original":"most criminals","simple":"most offenders","meaning":"大多數罪犯"},{"original":"reduce reoffending","simple":"reduce repeated crime","meaning":"減少再犯"},{"original":"repair damage","simple":"fix harm","meaning":"修補傷害"},{"original":"break the cycle of crime","simple":"stop the cycle of crime","meaning":"打破犯罪循環"}],"chunks":["I believe that rehabilitation and structured alternatives are better ways to deal with most criminals","because they reduce reoffending, repair damage,","and help society break the cycle of crime."],"simpleChunks":["I think helping offenders change and using carefully planned other punishments work better for most offenders","because they can reduce repeated crime, fix harm","and help society stop the cycle of crime."]}],"intro":[{"type":"quiz","prompt":"作者認為監獄是否處理大多數罪犯的最佳一般方法？","options":["不是：他主張改造及受嚴密監督的社區式刑罰通常更能處理犯罪成因","是：所有罪犯都應直接入獄，無須評估成因","不是：所以任何危險罪犯都可自由離開","沒有立場：只解釋監獄外觀"],"correct":0,"why":"not the best general solution、In most cases、carefully supervised... 共同限定作者立場。"},{"type":"multi","prompt":"選出本文兩條主要論證路線","detail":"選兩項，再按「確認」。","options":["單靠監禁或只處理表面，成癮、教育與就業問題未解時可出現再犯循環","懲罰可結合治療、職訓、社區工作與監管，協助重建及回饋社會","因監禁不完美，所有罪犯都不必承擔後果","任何社區刑罰均不需監管或考慮公眾安全"],"correct":[0,1],"why":"第一主體段談只監禁的成因缺口，第二段談懲罰與改造結合。"}],"route":[{"type":"sequence","prompt":"先排好全文四段","detail":"依照原文的推進次序，逐一點選下一步。","items":[{"title":"引言 · 反對一律入獄","body":"監禁看似直接，但作者認為多數情況下改造和受監督方案更有效。"},{"title":"主體段一 · 未治本的循環","body":"承認危險罪犯的安全風險；成癮、教育、失業等未解可令監禁成旋轉門。"},{"title":"主體段二 · 懲罰結合改造","body":"治療、職訓、社區服務與賠償可在嚴格監管下協助重建和回饋。"},{"title":"結論 · 依人與成因選方案","body":"改造及有結構替代方案對多數罪犯或能減少再犯並修補傷害。"}],"why":"監禁看似直接 → 成因未解帶來循環 → 受監管地追責和改造 → 多數情況較有用。"}],"evidence":[{"type":"quiz","prompt":"作者為何先說監禁支持者的看法「可以理解」？","options":["危險罪犯若自由可能傷害他人，因此保護公眾的顧慮真實","因為監獄已被證明能處理每種犯罪根源","因作者主張不論罪行都應一律入獄","因犯罪者不應有任何改造機會"],"correct":0,"why":"dangerous criminals can cause real harm if they remain free 是作者承認的安全條件。"},{"type":"quiz","prompt":"「處理症狀而非疾病」在本文指甚麼？","options":["監禁可暫時隔離或處罰人，但未必處理促成犯罪的問題","監獄是醫院，罪犯一律患有相同疾病","處理犯罪成因必然等於取消刑罰","作者說監獄完全不會懲罰罪行"],"correct":0,"why":"symptom/disease 是表面現象與根源的比喻，後文列成癮、教育與就業等。"},{"type":"quiz","prompt":"哪些問題可能使監獄變成「旋轉門」？","options":["成癮、教育不足、失業或家庭不穩等問題若被忽視，出獄時可能仍在","只要監獄的門會旋轉，便必定導致再犯","只要入獄一次，所有人的問題都必然完全消失","文章只提監獄建築，沒有提罪犯生活"],"correct":0,"why":"If these problems are ignored...return...same weaknesses 把未治成因連到循環。"},{"type":"quiz","prompt":"年輕輕微盜竊者的例子說明甚麼風險？","options":["出獄後或有較少工作機會，且與慣犯聯繫更深","所有輕微盜竊者必然成為重罪犯","監獄必然令每名青年找到理想工作","工作前景和犯罪循環完全無關"],"correct":0,"why":"may leave...fewer job prospects and stronger links... 是可能風險，不是全稱判斷。"},{"type":"quiz","prompt":"作者提出的社區式例子保留哪兩種要求？","options":["非暴力罪犯須工作和培訓，並遵守嚴格監管條件","罪犯可不工作，也不用接受培訓或監管","只要是社區工作，便保證任何人永不再犯","不需判斷罪行是否涉及暴力"],"correct":0,"why":"non-violent、work、training courses、strict supervision 同在例句中。"},{"type":"quiz","prompt":"「梯子而非牢籠」的比喻如何連到結論？","options":["懲罰仍追責，卻可給犯錯者可行回歸路徑，從而協助減少再犯","作者認為犯罪可被完全開脫","作者認為受害者的損害不用修補","懲罰只能把人關起，絕不能配合改造"],"correct":0,"why":"does not excuse the crime；realistic path back into society；reduce reoffending 連成完整論證。"}],"logic":[{"type":"sequence","prompt":"第一主體段：為何監禁可能只懲罰而未減罪？","detail":"依照原文的推進次序，逐一點選下一步。","items":[{"title":"先承認安全考慮","body":"危險罪犯若自由可能傷人，監禁支持者的顧慮可以理解。"},{"title":"再指出缺口","body":"監禁常處理症狀而未處理促成犯罪的問題。"},{"title":"可能成因","body":"成癮、教育不足、失業及家庭不穩。"},{"title":"未解後果","body":"罪犯服刑後可能帶着同樣或更嚴重問題回社會。"},{"title":"青年例子","body":"輕微盜竊者或失去工作前景並更接近慣犯。"},{"title":"段落結論","body":"監獄能懲罰犯罪，卻未必真正減少犯罪。"}],"why":"承認危險者風險 → 區分治標與治本 → 成因未解 → 出獄問題仍在 → 再犯風險。"},{"type":"sequence","prompt":"第二主體段：改造怎樣與懲罰並行？","detail":"依照原文的推進次序，逐一點選下一步。","items":[{"title":"提出結合","body":"更好的方法是把懲罰與改造合起來。"},{"title":"保留責任","body":"罪犯仍須承擔後果，並應重建生活與回饋社會。"},{"title":"可用措施","body":"治療、輔導、職訓、社區服務及受害者賠償。"},{"title":"具體安排","body":"非暴力者可做社區工作、參加培訓及遵守嚴格監管。"},{"title":"澄清誤解","body":"這並非開脫，而是把刑罰變成回歸社會的梯子。"},{"title":"全文回扣","body":"有結構替代方案可協助減少再犯、修補傷害和打破循環。"}],"why":"追責 → 實際改造與補償 → 嚴格監管的例子 → 回歸社會 → 社區更安全。"}],"structures":[{"id":"model-essay-33-ielts-opinion-frame-01","frame":"[犯罪] is [嚴重社會問題], and many people believe that [罪犯應直接入獄]","meaning":"以問題和常見處置作引言背景。","usage":"討論處理方法前，先說明公共問題與常見直覺做法時。","source":{"paragraph":1,"sentence":1},"parts":[{"text":"Crime","kind":"slot","label":"犯罪"},{"text":" is ","kind":"link","label":"是"},{"text":"a serious social problem","kind":"slot","label":"嚴重社會問題"},{"text":", and many people believe that ","kind":"link","label":"許多人因而認為"},{"text":"offenders should simply be sent to prison.","kind":"slot","label":"罪犯應直接入獄"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Pollution is a serious public problem, and many people believe that factories should simply be closed.","While closing a factory may seem the fastest response to pollution, I believe it is not always the best general solution.","In most cases, supervised alternatives work better because they address causes rather than merely hide the problem.","Supporters of school exclusion often argue that it protects others and warns pupils who might break rules."],"correct":0,"explanations":["and 接社會問題與常見直接解方，讓後句提出作者的不同判斷。","作者後文仍承認危險罪犯需防範，並非認為監獄永不適當。","重點是改造和受嚴密監督的社區刑罰，不是無監管放人。","作者下一句承認危險者可造成傷害，之後才批評監禁未治本。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-02","frame":"While [監禁看似最直接], I firmly believe that [它非一般最佳解]","meaning":"從直覺做法轉到作者立場，保留「看似」與「一般」的限定。","usage":"承認一種常用方法表面合理，再提出不同的整體評價時。","source":{"paragraph":1,"sentence":2},"parts":[{"text":"While ","kind":"link","label":"先讓步"},{"text":"imprisonment may appear to be the most direct response to criminal behaviour","kind":"slot","label":"監禁看似最直接"},{"text":", I firmly believe that ","kind":"link","label":"作者立場"},{"text":"it is not the best general solution.","kind":"slot","label":"它非一般最佳解"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["While closing a factory may seem the fastest response to pollution, I believe it is not always the best general solution.","Pollution is a serious public problem, and many people believe that factories should simply be closed.","In most cases, supervised alternatives work better because they address causes rather than merely hide the problem.","This concern is understandable because dangerous offenders can cause harm if left free."],"correct":0,"explanations":["While 讓步監禁看似直接；主句明確反對把它當一般最佳解。","這是問題背景及他人想法，尚非作者贊成一律入獄。","重點是改造和受嚴密監督的社區刑罰，不是無監管放人。","此句不是支持所有罪犯都一律入獄。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-03","frame":"In most cases, [改造與受監督社區刑罰] are more effective because [處理犯罪成因] rather than [只把罪犯藏起]","meaning":"引言先交代主張的適用範圍和核心因果對比。","usage":"反對某方法是一般最佳解後，要概括替代方向與原因時。","source":{"paragraph":1,"sentence":3},"parts":[{"text":"In most cases, ","kind":"link","label":"限定範圍"},{"text":"rehabilitation and carefully supervised community-based punishments","kind":"slot","label":"改造與受監督社區刑罰"},{"text":" are more effective because ","kind":"link","label":"更有效，因為"},{"text":"they address the causes of crime","kind":"slot","label":"處理犯罪成因"},{"text":" rather than ","kind":"link","label":"而非"},{"text":"merely hiding criminals from society.","kind":"slot","label":"只把罪犯藏起"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In most cases, supervised alternatives work better because they address causes rather than merely hide the problem.","While closing a factory may seem the fastest response to pollution, I believe it is not always the best general solution.","However, a policy can treat a symptom rather than its underlying cause.","A better approach is to combine discipline with support that helps people change."],"correct":0,"explanations":["In most cases 限定適用面；because...rather than... 對比處理成因與只隔離。","作者後文仍承認危險罪犯需防範，並非認為監獄永不適當。","這個句型的用途是區分眼前處置和深層原因，不局限監獄話題。","作者並未主張取消處罰或讓犯錯者沒有後果。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-04","frame":"Supporters of [監禁] often argue that it [保護公眾] and [警告潛在犯罪者]","meaning":"在反駁前先交代監禁支持者的兩項合理訴求。","usage":"回應反方前，要準確轉述其聲稱的作用時。","source":{"paragraph":2,"sentence":1},"parts":[{"text":"Supporters of ","kind":"link","label":"界定支持者"},{"text":"prison","kind":"slot","label":"監禁"},{"text":" often argue that it ","kind":"link","label":"常主張它"},{"text":"protects the public","kind":"slot","label":"保護公眾"},{"text":" and ","kind":"link","label":"並"},{"text":"sends a clear warning to potential offenders.","kind":"slot","label":"警告潛在犯罪者"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Supporters of school exclusion often argue that it protects others and warns pupils who might break rules.","While closing a factory may seem the fastest response to pollution, I believe it is not always the best general solution.","This concern is understandable because dangerous offenders can cause harm if left free.","However, a policy can treat a symptom rather than its underlying cause."],"correct":0,"explanations":["Supporters...argue 把保護與警告論點歸給支持監禁的人，先公平呈現反方。","作者後文仍承認危險罪犯需防範，並非認為監獄永不適當。","此句不是支持所有罪犯都一律入獄。","這個句型的用途是區分眼前處置和深層原因，不局限監獄話題。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-05","frame":"This view is understandable because [危險罪犯若自由可造成真實傷害]","meaning":"承認監禁在保護公眾上的合理考慮，讓後續批評更精確。","usage":"對方指出安全風險時，要公平承認特定危險情況時。","source":{"paragraph":2,"sentence":2},"parts":[{"text":"This view is understandable because ","kind":"link","label":"承認安全顧慮"},{"text":"dangerous criminals can cause real harm if they remain free.","kind":"slot","label":"危險罪犯若自由可造成真實傷害"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["This concern is understandable because dangerous offenders can cause harm if left free.","Supporters of school exclusion often argue that it protects others and warns pupils who might break rules.","However, a policy can treat a symptom rather than its underlying cause.","Many people break rules because of unmet needs, limited training, joblessness or unstable homes."],"correct":0,"explanations":["because 說明為何保護公眾的擔心可理解；if 指仍然自由的條件。","作者下一句承認危險者可造成傷害，之後才批評監禁未治本。","這個句型的用途是區分眼前處置和深層原因，不局限監獄話題。","Many 不等於每個罪犯都因這些原因犯案。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-06","frame":"However, [監獄] often treats [症狀] rather than [病因]","meaning":"將「能暫時隔離」與「能處理成因」區分開。","usage":"承認某措施能處理即時風險後，要指出它未觸及根源時。","source":{"paragraph":2,"sentence":3},"parts":[{"text":"However, ","kind":"link","label":"提出轉折"},{"text":"prison","kind":"slot","label":"監獄"},{"text":" often treats ","kind":"link","label":"常處理"},{"text":"the symptom","kind":"slot","label":"症狀"},{"text":" rather than ","kind":"link","label":"而非"},{"text":"the disease.","kind":"slot","label":"病因"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["However, a policy can treat a symptom rather than its underlying cause.","This concern is understandable because dangerous offenders can cause harm if left free.","Many people break rules because of unmet needs, limited training, joblessness or unstable homes.","If the causes are ignored, prison may become a revolving door: people enter, leave and return with the same problems."],"correct":0,"explanations":["However 轉入作者反駁；symptom/disease 比喻「表面現象／根源」。","此句不是支持所有罪犯都一律入獄。","Many 不等於每個罪犯都因這些原因犯案。","can become 只說風險，不是每位入獄者必然再犯。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-07","frame":"Many [罪犯] commit crimes because of [成癮、教育不足、失業或家庭不穩]","meaning":"用具體社會與個人因素展開犯罪成因。","usage":"提出「只治標」後，要列出可能被忽略的成因時。","source":{"paragraph":2,"sentence":4},"parts":[{"text":"Many ","kind":"link","label":"討論不少案例"},{"text":"offenders","kind":"slot","label":"罪犯"},{"text":" commit crimes because of ","kind":"link","label":"可能因"},{"text":"addiction, poor education, unemployment, or unstable family backgrounds.","kind":"slot","label":"成癮、教育不足、失業或家庭不穩"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Many people break rules because of unmet needs, limited training, joblessness or unstable homes.","However, a policy can treat a symptom rather than its underlying cause.","If the causes are ignored, prison may become a revolving door: people enter, leave and return with the same problems.","For example, a young minor offender may leave prison with fewer work chances and stronger links to serious criminals."],"correct":0,"explanations":["because of 引入多種可能成因，具體解釋前句「病因」。","這個句型的用途是區分眼前處置和深層原因，不局限監獄話題。","can become 只說風險，不是每位入獄者必然再犯。","may leave 表可能後果，不可推成所有青年必然如此。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-08","frame":"If [這些問題被忽略], [監獄] can become [旋轉門]: [入獄、服刑、帶着同樣或更差問題回來]","meaning":"把成因未解連到刑滿後可能重回困境的循環。","usage":"列出深層成因後，要說明不處理的長期後果時。","source":{"paragraph":2,"sentence":5},"parts":[{"text":"If ","kind":"link","label":"設定未處理條件"},{"text":"these problems are ignored","kind":"slot","label":"這些問題被忽略"},{"text":", ","kind":"link","label":"接可能後果"},{"text":"prison","kind":"slot","label":"監獄"},{"text":" can become ","kind":"link","label":"可能變成"},{"text":"a revolving door","kind":"slot","label":"旋轉門"},{"text":": ","kind":"link","label":"具體循環"},{"text":"criminals enter, serve their sentence, and return to society with the same weaknesses, or sometimes even worse ones.","kind":"slot","label":"入獄、服刑、帶着同樣或更差問題回來"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["If the causes are ignored, prison may become a revolving door: people enter, leave and return with the same problems.","Many people break rules because of unmet needs, limited training, joblessness or unstable homes.","For example, a young minor offender may leave prison with fewer work chances and stronger links to serious criminals.","In this sense, a policy may punish misconduct without actually preventing it."],"correct":0,"explanations":["If 設未處理成因條件；revolving door 比喻出獄後問題仍在的循環。","Many 不等於每個罪犯都因這些原因犯案。","may leave 表可能後果，不可推成所有青年必然如此。","不是說監獄完全無懲罰作用；正是它可以懲罰但未必減罪。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-09","frame":"For example, [犯輕微盜竊的青年] may leave prison with [較少工作機會及較深慣犯聯繫]","meaning":"以一名輕罪者的具體處境示範成因未解可惡化。","usage":"提出反覆問題的風險後，要以個案展示關係與機會如何受損時。","source":{"paragraph":2,"sentence":6},"parts":[{"text":"For example, ","kind":"link","label":"舉例"},{"text":"a young person who commits a minor theft","kind":"slot","label":"犯輕微盜竊的青年"},{"text":" may leave prison with ","kind":"link","label":"出獄後可能有"},{"text":"fewer job prospects and stronger links to hardened criminals.","kind":"slot","label":"較少工作機會及較深慣犯聯繫"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["For example, a young minor offender may leave prison with fewer work chances and stronger links to serious criminals.","If the causes are ignored, prison may become a revolving door: people enter, leave and return with the same problems.","In this sense, a policy may punish misconduct without actually preventing it.","A better approach is to combine discipline with support that helps people change."],"correct":0,"explanations":["For example 用輕微盜竊青年說明「旋轉門」如何形成。","can become 只說風險，不是每位入獄者必然再犯。","不是說監獄完全無懲罰作用；正是它可以懲罰但未必減罪。","作者並未主張取消處罰或讓犯錯者沒有後果。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-10","frame":"In this sense, [監獄] can [懲罰罪行] without [真正減罪]","meaning":"把主體段例子收束為懲罰與預防不必然相同。","usage":"列出原因未解與回歸困難後，要指出單靠處罰的限制時。","source":{"paragraph":2,"sentence":7},"parts":[{"text":"In this sense, ","kind":"link","label":"概括上述例子"},{"text":"prison","kind":"slot","label":"監獄"},{"text":" can ","kind":"link","label":"能"},{"text":"punish crime","kind":"slot","label":"懲罰罪行"},{"text":" without ","kind":"link","label":"卻未必"},{"text":"actually reducing it.","kind":"slot","label":"真正減罪"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In this sense, a policy may punish misconduct without actually preventing it.","However, a policy can treat a symptom rather than its underlying cause.","If the causes are ignored, prison may become a revolving door: people enter, leave and return with the same problems.","Offenders should face consequences, but those consequences should help them rebuild and repay society."],"correct":0,"explanations":["In this sense 回扣青年例子；without actually reducing it 分開「懲罰」與「減少犯罪」兩個目標。","這個句型的用途是區分眼前處置和深層原因，不局限監獄話題。","can become 只說風險，不是每位入獄者必然再犯。","「改造」不是赦免犯罪，而是重新設計懲罰後的路徑。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-11","frame":"A better approach is to combine [懲罰] with [改造]","meaning":"提出第三段核心方案：處罰與改造共同運作。","usage":"指出一種方法有即時作用但未必改善長遠結果後，要提出兼顧方案時。","source":{"paragraph":3,"sentence":1},"parts":[{"text":"A better approach is to combine ","kind":"link","label":"提出結合方法"},{"text":"punishment","kind":"slot","label":"懲罰"},{"text":" with ","kind":"link","label":"和"},{"text":"rehabilitation.","kind":"slot","label":"改造"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["A better approach is to combine discipline with support that helps people change.","In this sense, a policy may punish misconduct without actually preventing it.","Offenders should face consequences, but those consequences should help them rebuild and repay society.","Treatment, counselling, job training and payments to victims can make a penalty more constructive."],"correct":0,"explanations":["combine...with... 把懲罰與改造並列，直接回應上一段缺口。","不是說監獄完全無懲罰作用；正是它可以懲罰但未必減罪。","「改造」不是赦免犯罪，而是重新設計懲罰後的路徑。","措施可各有不同作用，並非每名罪犯都需要全部五項。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-12","frame":"[罪犯] should still [承擔後果], but [那些後果] should help [重建生活及回饋社會]","meaning":"釐清懲罰與改造並行的具體意義。","usage":"提出改造方案後，要避免被誤解為免除責任時。","source":{"paragraph":3,"sentence":2},"parts":[{"text":"Offenders","kind":"slot","label":"罪犯"},{"text":" should still ","kind":"link","label":"仍應"},{"text":"face consequences","kind":"slot","label":"承擔後果"},{"text":", but ","kind":"link","label":"但"},{"text":"those consequences","kind":"slot","label":"那些後果"},{"text":" should help ","kind":"link","label":"應協助"},{"text":"them rebuild their lives and repay society.","kind":"slot","label":"重建生活及回饋社會"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Offenders should face consequences, but those consequences should help them rebuild and repay society.","A better approach is to combine discipline with support that helps people change.","Treatment, counselling, job training and payments to victims can make a penalty more constructive.","For instance, someone convicted of a non-violent offence could work in the community while taking courses under strict supervision."],"correct":0,"explanations":["should still...but... 保留追責，並要求刑罰協助重建及回饋。","作者並未主張取消處罰或讓犯錯者沒有後果。","措施可各有不同作用，並非每名罪犯都需要全部五項。","could 是一個可能量刑例子，非所有非暴力案件的必然處置。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-13","frame":"[治療、輔導、職訓、社區服務及受害者賠償] can make [懲罰] more [有建設性]","meaning":"列出可按個案組合的實際改造與補償手段。","usage":"主張一項制度應協助修復後，要列出不同操作方式時。","source":{"paragraph":3,"sentence":3},"parts":[{"text":"Drug treatment, psychological counselling, vocational training, community service, and victim compensation","kind":"slot","label":"治療、輔導、職訓、社區服務及受害者賠償"},{"text":" can all make ","kind":"link","label":"都可使"},{"text":"punishment","kind":"slot","label":"懲罰"},{"text":" more ","kind":"link","label":"更"},{"text":"constructive.","kind":"slot","label":"有建設性"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["Treatment, counselling, job training and payments to victims can make a penalty more constructive.","A better approach is to combine discipline with support that helps people change.","Offenders should face consequences, but those consequences should help them rebuild and repay society.","For instance, someone convicted of a non-violent offence could work in the community while taking courses under strict supervision."],"correct":0,"explanations":["多項措施作主語，can make...constructive 具體化如何同時改造及回饋。","作者並未主張取消處罰或讓犯錯者沒有後果。","「改造」不是赦免犯罪，而是重新設計懲罰後的路徑。","could 是一個可能量刑例子，非所有非暴力案件的必然處置。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-14","frame":"For instance, [非暴力罪犯] could [做社區工作] while [參加培訓並遵守嚴格監管]","meaning":"用完整條件展示有結構的社區式刑罰，而非無監管放人。","usage":"列出方法後，要用合適人物說明責任與改善如何並存時。","source":{"paragraph":3,"sentence":4},"parts":[{"text":"For instance, ","kind":"link","label":"舉量刑例子"},{"text":"someone who has committed a non-violent offence","kind":"slot","label":"非暴力罪犯"},{"text":" could be required to ","kind":"link","label":"可被要求"},{"text":"work in the community","kind":"slot","label":"做社區工作"},{"text":" while ","kind":"link","label":"同時"},{"text":"attending training courses and meeting strict supervision conditions.","kind":"slot","label":"參加培訓並遵守嚴格監管"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["For instance, someone convicted of a non-violent offence could work in the community while taking courses under strict supervision.","Offenders should face consequences, but those consequences should help them rebuild and repay society.","Treatment, counselling, job training and payments to victims can make a penalty more constructive.","This approach does not excuse the mistake; rather, it turns discipline into a ladder instead of a cage."],"correct":0,"explanations":["For instance 提適用者；while 把社區工作、培訓和嚴格監管同時安排。","「改造」不是赦免犯罪，而是重新設計懲罰後的路徑。","措施可各有不同作用，並非每名罪犯都需要全部五項。","梯子比喻幫助回歸；不表示罪行沒有後果。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-15","frame":"This approach does not [為罪行開脫]; rather, it turns [懲罰] into [梯子] instead of [牢籠]","meaning":"用對照比喻說明懲罰可開出改變路徑，而非只隔離。","usage":"有人把改善措施誤解成縱容時，要先澄清再說明實際功能時。","source":{"paragraph":3,"sentence":5},"parts":[{"text":"This approach does not ","kind":"link","label":"先否定誤解"},{"text":"excuse the crime","kind":"slot","label":"為罪行開脫"},{"text":"; rather, it turns ","kind":"link","label":"相反，它把"},{"text":"punishment","kind":"slot","label":"懲罰"},{"text":" into ","kind":"link","label":"化作"},{"text":"a ladder","kind":"slot","label":"梯子"},{"text":" instead of ","kind":"link","label":"而非"},{"text":"a cage.","kind":"slot","label":"牢籠"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["This approach does not excuse the mistake; rather, it turns discipline into a ladder instead of a cage.","Offenders should face consequences, but those consequences should help them rebuild and repay society.","For instance, someone convicted of a non-violent offence could work in the community while taking courses under strict supervision.","It offers people a realistic path back into society, which can make communities safer."],"correct":0,"explanations":["does not...; rather... 明確否定縱容並提出梯子／牢籠的對照。","「改造」不是赦免犯罪，而是重新設計懲罰後的路徑。","could 是一個可能量刑例子，非所有非暴力案件的必然處置。","文章說 ultimately makes，仍須有可行回歸與結構化安排支持。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-16","frame":"It gives [罪犯] [實際回歸社會之路], which [令社區更安全]","meaning":"由犯錯者的改造路徑推至公共安全。","usage":"解釋一個比喻後，要指出它對更廣群體的好處時。","source":{"paragraph":3,"sentence":6},"parts":[{"text":"It gives ","kind":"link","label":"提供"},{"text":"offenders","kind":"slot","label":"罪犯"},{"text":" ","kind":"link","label":"一條"},{"text":"a realistic path back into society","kind":"slot","label":"實際回歸社會之路"},{"text":", which ultimately ","kind":"link","label":"最終可能"},{"text":"makes communities safer.","kind":"slot","label":"令社區更安全"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["It offers people a realistic path back into society, which can make communities safer.","For instance, someone convicted of a non-violent offence could work in the community while taking courses under strict supervision.","This approach does not excuse the mistake; rather, it turns discipline into a ladder instead of a cage.","In conclusion, prison may appear strong, but it can be too blunt a tool."],"correct":0,"explanations":["which 連接回歸路徑與社區安全，不把改造只寫成罪犯個人利益。","could 是一個可能量刑例子，非所有非暴力案件的必然處置。","梯子比喻幫助回歸；不表示罪行沒有後果。","作者沒有說監獄永遠不適用，前文已承認危險罪犯的安全風險。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-17","frame":"In conclusion, [監獄] may look like [有力解方], but it is often [粗糙工具]","meaning":"結論用讓步與評價對照監禁表面威力及實際限制。","usage":"完成原方案與替代方案比較後，要重申哪個一般較好時。","source":{"paragraph":4,"sentence":1},"parts":[{"text":"In conclusion, ","kind":"link","label":"總結"},{"text":"prison","kind":"slot","label":"監獄"},{"text":" may look like ","kind":"link","label":"看似"},{"text":"a strong solution","kind":"slot","label":"有力解方"},{"text":", but it is often ","kind":"link","label":"卻往往是"},{"text":"a blunt instrument.","kind":"slot","label":"粗糙工具"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["In conclusion, prison may appear strong, but it can be too blunt a tool.","This concern is understandable because dangerous offenders can cause harm if left free.","In this sense, a policy may punish misconduct without actually preventing it.","I believe rehabilitation and structured alternatives work better for most offenders because they reduce repeat crime and repair harm."],"correct":0,"explanations":["may look...but... 承認監禁外觀有力，再以 blunt instrument 評價其針對性不足。","此句不是支持所有罪犯都一律入獄。","不是說監獄完全無懲罰作用；正是它可以懲罰但未必減罪。","作者不是主張所有危險罪犯都可用社區刑罰取代監禁。"],"patternType":"reviewed"},{"id":"model-essay-33-ielts-opinion-frame-18","frame":"I believe that [改造與有結構替代方案] are better for [大多數罪犯] because [減少再犯、修補傷害及打破循環]","meaning":"結論重述適用範圍，並串起成因處理與社區安全。","usage":"最後一句要合併替代方案與幾項預期結果時。","source":{"paragraph":4,"sentence":2},"parts":[{"text":"I believe that ","kind":"link","label":"表明結論"},{"text":"rehabilitation and structured alternatives","kind":"slot","label":"改造與有結構替代方案"},{"text":" are better ways to deal with ","kind":"link","label":"較能處理"},{"text":"most criminals","kind":"slot","label":"大多數罪犯"},{"text":" because ","kind":"link","label":"因為"},{"text":"they reduce reoffending, repair damage, and help society break the cycle of crime.","kind":"slot","label":"減少再犯、修補傷害及打破循環"}],"prompt":"哪一句正確用了上面標示的句型及其功能？","options":["I believe rehabilitation and structured alternatives work better for most offenders because they reduce repeat crime and repair harm.","In most cases, supervised alternatives work better because they address causes rather than merely hide the problem.","A better approach is to combine discipline with support that helps people change.","In conclusion, prison may appear strong, but it can be too blunt a tool."],"correct":0,"explanations":["most 限定適用者；because 列再犯、修補及犯罪循環三個社會效益。","重點是改造和受嚴密監督的社區刑罰，不是無監管放人。","作者並未主張取消處罰或讓犯錯者沒有後果。","作者沒有說監獄永遠不適用，前文已承認危險罪犯的安全風險。"],"patternType":"reviewed"}],"transfer":[{"type":"quiz","prompt":"依本文，哪項是必須保留的安全考慮？","context":"社區討論一名具嚴重暴力風險的罪犯是否可立即無監管回家。","question":"依本文，哪項是必須保留的安全考慮？","options":["危險者若自由可能傷害他人，公共安全不能被改造方案忽略","因監禁不完美，危險者便不需要任何監管","只要提出改造，便可取消所有保護措施","文章認為危險罪犯永遠不會傷害他人"],"correct":0,"explanations":["This view is understandable because dangerous criminals can cause real harm if they remain free。","否定了原文安全讓步。","改造仍需安全條件。","與原句相反。"],"why":"This view is understandable because dangerous criminals can cause real harm if they remain free。","sourceSentenceIndices":[3,4,13],"modelLink":"dangerous criminals can cause real harm if they remain free。"},{"type":"quiz","prompt":"哪項可轉用「症狀與疾病」的邏輯？","context":"一個教育計劃只把屢次缺課學生停課，卻不查明交通、家庭或學習困難。","question":"哪項可轉用「症狀與疾病」的邏輯？","options":["停課可處理眼前行為，仍須找出反覆缺課的成因","停課本身會自動解決所有家庭困難","只要追查原因，學生便毋須承擔任何後果","反覆缺課的原因必然只有一種"],"correct":0,"explanations":["原文區分眼前處置與未被解決的深層原因。","根源不會自動消失。","第二段保留追責。","原文列多種成因。"],"why":"原文區分眼前處置與未被解決的深層原因。","sourceSentenceIndices":[5,6,7,10],"modelLink":"prison often treats the symptom rather than the disease 是一般可轉用的因果區分。"},{"type":"quiz","prompt":"哪項最合「旋轉門」比喻？","context":"一名輕罪者出獄時仍有成癮問題，沒有工作機會，也缺乏支援。","question":"哪項最合「旋轉門」比喻？","options":["若根源未處理，服刑後可能帶着同樣或更差困境回社會","只要已服刑，成癮和失業便必然消失","「旋轉門」只在描述監獄入口的設計","任何出獄者必然再犯，沒有改變可能"],"correct":0,"explanations":["If these problems are ignored...same weaknesses 說的是風險循環。","與原文條件相反。","比喻不是建築說明。","can become 並非必然。"],"why":"If these problems are ignored...same weaknesses 說的是風險循環。","sourceSentenceIndices":[6,7,8,9],"modelLink":"If these problems are ignored, prison can become a revolving door。"},{"type":"quiz","prompt":"哪項最能保留原文的兩個目標？","context":"有人說：「監獄能懲罰犯罪，所以一定也能減少往後的犯罪。」","question":"哪項最能保留原文的兩個目標？","options":["能懲罰不等於必定減罪，仍要看成因是否處理及出獄後條件","只要罪犯受處罰，所有社會壓力便自動消除","監獄完全不具有任何懲罰作用","減罪和懲罰是同一個概念，無需分開"],"correct":0,"explanations":["In this sense...punish crime without actually reducing it 是明確區分。","原文認為成因可能未解。","原文承認監獄可懲罰。","兩者效果須分開評估。"],"why":"In this sense...punish crime without actually reducing it 是明確區分。","sourceSentenceIndices":[5,7,8,9],"modelLink":"prison can punish crime without actually reducing it。"},{"type":"quiz","prompt":"哪項最貼近第三段？","context":"地方政府考慮罪犯重返社區方案：只有輔導、沒有責任要求；或只有處罰、沒有支援。","question":"哪項最貼近第三段？","options":["把後果與改造結合，要求承擔責任並提供重建與回饋路徑","只提供輔導，犯罪後果可一筆勾銷","只施處罰，成因與回歸社會都不必考慮","只要方案名稱寫着「改造」，便不用實際措施"],"correct":0,"explanations":["combine punishment with rehabilitation；face consequences...rebuild and repay。","原文不開脫犯罪。","原文反對只處理表面。","文章列具體措施。"],"why":"combine punishment with rehabilitation；face consequences...rebuild and repay。","sourceSentenceIndices":[10,11,12,14],"modelLink":"A better approach is to combine punishment with rehabilitation。"},{"type":"quiz","prompt":"這個安排為何符合原文？","context":"一名非暴力罪犯接受社區工作，並須定期上培訓課及向監督人員報告。","question":"這個安排為何符合原文？","options":["它同時有工作責任、技能建立和嚴格監管","因是非暴力罪犯，所以完全不須承擔後果","社區工作只要掛名，不需完成或監督","原文要求所有危險罪犯都照此安排"],"correct":0,"explanations":["原文量刑例子正是 work、training courses、strict supervision 的組合。","文章保留懲罰。","原文要求 strict supervision。","例子只用非暴力者。"],"why":"原文量刑例子正是 work、training courses、strict supervision 的組合。","sourceSentenceIndices":[11,12,13],"modelLink":"work in the community while attending training courses and meeting strict supervision conditions。"},{"type":"quiz","prompt":"原文的措施清單提醒甚麼？","context":"某政策只提供職訓，沒有處理成癮；另一政策只提供治療，沒有幫助就業。","question":"原文的措施清單提醒甚麼？","options":["可依個案需要組合治療、輔導、職訓、社區工作與賠償","每個人都必須同時接受所有措施，無論是否適用","只要其中一項措施存在，其他問題便必然消失","措施清單只是裝飾，與懲罰是否有建設性無關"],"correct":0,"explanations":["原文列多種可令懲罰更有建設性的方式，需按成因和需要運用。","原文沒有每人全套要求。","成因可不同。","清單是實際方案。"],"why":"原文列多種可令懲罰更有建設性的方式，需按成因和需要運用。","sourceSentenceIndices":[6,10,11,12],"modelLink":"Drug treatment...vocational training...victim compensation can all make punishment more constructive。"},{"type":"quiz","prompt":"哪項回應最忠於「梯子而非牢籠」？","context":"評論者說：「社區工作就是替犯罪開脫。」","question":"哪項回應最忠於「梯子而非牢籠」？","options":["社區工作仍是受監督的後果，但可提供修補傷害及回歸社會的路徑","犯罪既然發生，就完全不用要求任何補償","改造只為了讓罪犯避開嚴格條件","「梯子」表示不用處理受害者損害"],"correct":0,"explanations":["does not excuse the crime; rather...a ladder 指追責中的改變路徑。","原文明說 face consequences。","例子明說 strict supervision。","賠償是措施之一。"],"why":"does not excuse the crime; rather...a ladder 指追責中的改變路徑。","sourceSentenceIndices":[11,12,13,14,15],"modelLink":"This approach does not excuse the crime; rather, it turns punishment into a ladder。"},{"type":"quiz","prompt":"哪項修正最準確？","context":"一位學生把文章概括為：「作者認為所有罪犯都可用社區服務代替監禁。」","question":"哪項修正最準確？","options":["作者談大多數情況及非暴力例子，同時承認危險者自由可能傷人","無須修正，因文章從未提危險罪犯","改成作者主張所有罪犯只應直接入獄","改成文章認為改造完全不能減少再犯"],"correct":0,"explanations":["In most cases、non-violent 和 dangerous criminals 的讓步限制範圍。","文中明確談危險者。","作者反對監禁作一般最佳解。","結論主張改造可減再犯。"],"why":"In most cases、non-violent 和 dangerous criminals 的讓步限制範圍。","sourceSentenceIndices":[1,2,4,13,17],"modelLink":"In most cases...；dangerous criminals can cause real harm if free。"},{"type":"quiz","prompt":"哪項最能連結兩段理由？","context":"一個修復計劃要求犯錯者賠償受害者，也安排職訓，讓他們之後較易找到工作。","question":"哪項最能連結兩段理由？","options":["既修補損害，又處理缺乏技能等可能推動再犯的問題","有了賠償便不用再考慮成因或就業","職訓可保證每人完全不會再犯","修復計劃等於讓犯錯者不需承擔任何後果"],"correct":0,"explanations":["第一段指出工作前景風險，第二段列職訓與賠償作建設性措施。","文章主張兼顧。","沒有必然保證。","賠償就是後果之一。"],"why":"第一段指出工作前景風險，第二段列職訓與賠償作建設性措施。","sourceSentenceIndices":[6,8,11,12,17],"modelLink":"vocational training 和 victim compensation 可令懲罰更有建設性。"},{"type":"quiz","prompt":"文章如何建立後者的推理？","context":"有人說只有把人長期隔離，社區才會更安全；另一人說回歸計劃可能改善安全。","question":"文章如何建立後者的推理？","options":["可行回歸路徑或減少再犯、修補傷害，因而有助社區安全","只要某人出獄，社區便必然立刻安全","社區安全只取決於監獄外觀是否嚴厲","文章完全不關心公眾可能受害的風險"],"correct":0,"explanations":["realistic path...which makes communities safer 與結論三項效益相連。","文章談途徑不是保證。","外觀有力未必有效。","文中承認危險者風險。"],"why":"realistic path...which makes communities safer 與結論三項效益相連。","sourceSentenceIndices":[4,14,15,16,17],"modelLink":"realistic path back into society, which ultimately makes communities safer。"},{"type":"quiz","prompt":"哪項最準確？","context":"小組需要一段不過度概括本文的總結。","question":"哪項最準確？","options":["對大多數合適罪犯，懲罰配合改造和嚴格監管或較能處理成因並減少再犯","監獄對任何危險罪犯都沒有保護作用","只要有社區服務，其他治療與培訓便不再重要","作者反對要求罪犯回饋社會或修補傷害"],"correct":0,"explanations":["most、carefully supervised、rehabilitation、reoffending 保留全文範圍與因果。","第一段承認危險者風險。","文章列多項措施。","回饋和修補是第二段重點。"],"why":"most、carefully supervised、rehabilitation、reoffending 保留全文範圍與因果。","sourceSentenceIndices":[2,4,10,11,12,13,17],"modelLink":"rehabilitation and structured alternatives...most criminals...reduce reoffending, repair damage。"}],"mediumExtras":[]};})();
